import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.BN3Eol-0.js";const g=JSON.parse('{"title":"UXS-017 — The gallery: the hub, the deep-sky viewer, the note under the pages","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/UXS-017.md","filePath":"uxs/UXS-017.md"}'),r={name:"uxs/UXS-017.md"};function i(d,e,h,n,l,c){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="uxs-017-—-the-gallery-the-hub-the-deep-sky-viewer-the-note-under-the-pages" tabindex="-1">UXS-017 — The gallery: the hub, the deep-sky viewer, the note under the pages <a class="header-anchor" href="#uxs-017-—-the-gallery-the-hub-the-deep-sky-viewer-the-note-under-the-pages" aria-label="Permalink to &quot;UXS-017 — The gallery: the hub, the deep-sky viewer, the note under the pages&quot;">​</a></h1><blockquote><p>Status · Draft v0.1 Extends · UXD-009 (the viewer fits one screen), UXD-012 (the page shell), UXD-040 (the build of both) Related · IA §page-shell · Design System §4.6 (<code>.page-note</code>) and §5.21 (the viewer) Visual fidelity · Spec-only; checked against the built pages by <code>tests/e2e/gallery.spec.ts</code></p></blockquote><h2 id="why-this-uxs-exists" tabindex="-1">Why this UXS exists <a class="header-anchor" href="#why-this-uxs-exists" aria-label="Permalink to &quot;Why this UXS exists&quot;">​</a></h2><p><a href="./UXS-000-orrery-ux-architecture">UXS-000</a> §Next listed &quot;no spec yet for the deep-sky viewer&quot;: the gallery family (<code>/gallery</code>, <code>/gallery/deep-sky</code>, <code>/posters</code>, <code>/patches</code>, <code>/sourcing</code>) had no spec. This one holds the rules that the spec guards.</p><h2 id="_1-·-the-hub-gallery" tabindex="-1">1 · The hub (<code>/gallery</code>) <a class="header-anchor" href="#_1-·-the-hub-gallery" aria-label="Permalink to &quot;1 · The hub (`/gallery`)&quot;">​</a></h2><p>Three strips (deep-sky, posters, insignia), each a link over a row of the collection&#39;s real thumbnails with a scrim and its text; the text starts on the page title&#39;s left edge. A strip&#39;s height is a minimum: the text sets it, so none of it is clipped. Posters and insignia keep the art beside the text (the text in the left 40%, the art from 40%); on a phone the art sits behind the text under a heavier scrim.</p><h2 id="_2-·-the-deep-sky-viewer-gallery-deep-sky" tabindex="-1">2 · The deep-sky viewer (<code>/gallery/deep-sky</code>) <a class="header-anchor" href="#_2-·-the-deep-sky-viewer-gallery-deep-sky" aria-label="Permalink to &quot;2 · The deep-sky viewer (`/gallery/deep-sky`)&quot;">​</a></h2><p>The grid of tiles opens a full-window viewer. <strong>Rule: the viewer fits one screen.</strong> At 1366x768 and 1440x900 the image, the facts row (label above value), the credit line and the &quot;show in the sky&quot; button are inside the window with the image at least 300 px high, for every image and every locale. The image takes the height the caption stack leaves; on a phone, or in a window too short for both, the figure scrolls and every element stays reachable. The caption keeps italic at <code>--size-caption</code> (UXD-002); the facility line and designation are not teal. The button&#39;s text is the page background token on the accent gradient (4.96:1 on the dark end of the gradient).</p><h2 id="_3-·-the-note-gallery-deep-sky-posters-patches-sourcing" tabindex="-1">3 · The note (<code>/gallery/deep-sky</code>, <code>/posters</code>, <code>/patches</code>, <code>/sourcing</code>) <a class="header-anchor" href="#_3-·-the-note-gallery-deep-sky-posters-patches-sourcing" aria-label="Permalink to &quot;3 · The note (`/gallery/deep-sky`, `/posters`, `/patches`, `/sourcing`)&quot;">​</a></h2><p>Each page ends with one <code>&lt;footer class=&quot;page-note&quot;&gt;</code>: the shell&#39;s note, the same in all four (Design System §4.6). A page writes no footer rule of its own.</p><h2 id="_4-·-the-card-grid-patches-posters-essays-too" tabindex="-1">4 · The card grid (<code>/patches</code>, <code>/posters</code>; <code>/essays</code> too) <a class="header-anchor" href="#_4-·-the-card-grid-patches-posters-essays-too" aria-label="Permalink to &quot;4 · The card grid (`/patches`, `/posters`; `/essays` too)&quot;">​</a></h2><p><code>/patches</code> and <code>/posters</code> (and the <code>/essays</code> index) draw the catalogue&#39;s card in the catalogue&#39;s grid (<code>EntityCard</code> in <code>ul.entity-card-grid</code>, Design System §5.4, UXD-048) so the site reads as one design: the same grid rule and gap as <code>/missions</code>, one card size per grid, the same name type. They keep the 1080 px reading frame (<code>page-shell</code>) while <code>/missions</code> and <code>/fleet</code> use the wide one, so the grid gives 3 columns at 1440 against 5. An insignia is shown whole (<code>fit=&quot;contain&quot;</code>) over a name and its credit and licence line, 294 px at 1440; a poster is a 2:3 photo and nothing else, 499 px, still a download link in the spatial roving group; an essay is the editorial variant (<code>editorial</code>): a wide photo, the title on two lines and three lines of the dek in the editorial serif, 330 px, one column under 600 px so a long title fits (de and ar read at 390). No era strip and no agency chips: those pages carry no eras or agencies.</p><h2 id="guards" tabindex="-1">Guards <a class="header-anchor" href="#guards" aria-label="Permalink to &quot;Guards&quot;">​</a></h2><p><code>tests/e2e/gallery.spec.ts</code> (viewer fit at both laptop sizes, the phone scroll, the note&#39;s computed style across the four pages, the strips&#39; text), <code>tests/e2e/page-shell.spec.ts</code> (the strip&#39;s left edge), <code>tests/e2e/a11y.spec.ts</code> (the gallery rows), <code>tests/e2e/catalogue-pattern.spec.ts</code> (§4: one card size per grid, no empty band over 50 px, the catalogue&#39;s gap, 3 columns at 1100 px and up, one essay column on a phone, the essay body, poster download links, insignia credit links).</p>',14)])])}const u=t(r,[["render",i]]);export{g as __pageData,u as default};
